#!/usr/bin/env node
// Packs the settings, sample messages and recorded AI responses into bundle.js so index.html also works
// when opened straight from the disk (file://), where browsers block fetch().
'use strict';
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..');
const read = (p, dflt) => fs.existsSync(path.join(root, p)) ? JSON.parse(fs.readFileSync(path.join(root, p), 'utf8')) : dflt;
const bundle = {
  profile: read('config/school_profile.json'),
  samples: read('data/sample_inquiries.json', { items: [] }),
  recorded: read('data/recorded_ai_responses.json', { reads: {}, drafts: {} })
};
fs.writeFileSync(path.join(root, 'bundle.js'), '/* generated by tools/build_bundle.js - do not edit */\nwindow.AA_BUNDLE = ' + JSON.stringify(bundle) + ';\n');
console.log('bundle.js written');
